  return (
    <ReducedMotionConfig>
      <AriaProgressBar
        {...props}
        render={(domProps, renderProps) => (
          <ProgressBarMotion
            domProps={domProps}
            render={render ? (p) => render(p, renderProps) : undefined}
            moveTransition={transition}
          />
        )}
      />
    </ReducedMotionConfig>
  );
