  const y = rect.top + rect.height / 2;
  for (const list of document.querySelectorAll('[role="listbox"]')) {
    if (list.contains(el)) continue;
    const box = list.getBoundingClientRect();
    if (x < box.left || x > box.right || y < box.top || y > box.bottom)
